query ItemPageQuery(
  $term: String = ""
) {
  ...ItemList_query_4hh6ED
}

fragment ItemList_query_4hh6ED on RootQuery {
  clogItemSearch(first: 25, where: {term: $term}) {
    totalCount
    edges {
      node {
        id
        name
        barcode
        createdAt
        stockCount
        __typename
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

